// Merge the moves and learnsets into D (called from data.js indexData()).
export function applyGen4Moves(D, { MOVES, LEARN }) {
  for (const [key, [effect, chance, desc, extra]] of Object.entries(GEN4_MOVES)) {
    const s = MOVES[key];
    if (!s || D.moves[key]) continue;
    D.moves[key] = {
      id: s.id, name: s.name, effect, power: s.power, type: s.type, accuracy: s.accuracy, pp: s.pp, chance,
      target: s.power ? 'SELECTED' : 'USER', priority: s.priority,
      flags: s.contact ? ['MAKES_CONTACT', 'PROTECT_AFFECTED', 'MIRROR_MOVE_AFFECTED'] : s.power ? ['PROTECT_AFFECTED', 'MIRROR_MOVE_AFFECTED'] : ['SNATCH_AFFECTED'],
      desc, gen: 4, ...(extra || {}),
    };
  }
  for (const [sp, { level, tmhm, tutor }] of Object.entries(LEARN)) {
    const s = D.species[sp];
    if (!s) continue;
    if (level?.length) {
      // Level 1 moves go first so they don't push out a low-level mon's usual moves; others slot in after
      // any FireRed moves at the same level (learnsets stay sorted, which defaultMoves() relies on).
      const ls = (s.learnset || []).slice();
      for (const [lvl, mv] of level) {
        if (!D.moves[mv] || ls.some(([, m]) => m === mv)) continue;
        let i = lvl <= 1 ? 0 : ls.findIndex(([l]) => l > lvl);
        if (i < 0) i = ls.length;
        ls.splice(i, 0, [lvl, mv]);
      }
      s.learnset = ls;
    }
    if (tmhm?.length) s.tmhm = [...(s.tmhm || []), ...tmhm.filter(m => D.moves[m] && !(s.tmhm || []).includes(m))];
    if (tutor?.length) s.tutor = [...(s.tutor || []), ...tutor.filter(m => D.moves[m] && !(s.tutor || []).includes(m))];
  }
}
